-- Writer identity, explicitly selected showcase, taxonomy and genuine social signals.
alter table public.midad_profiles add column tagline text not null default '' check(length(tagline)<=100),add column location text not null default '' check(length(location)<=80),add column avatar_path text,add column banner_path text;
alter table public.midad_profiles add constraint profile_avatar_owned check(avatar_path is null or avatar_path like user_id::text||'/%'),add constraint profile_banner_owned check(banner_path is null or banner_path like user_id::text||'/%');
create table public.midad_profile_links(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,label text not null check(length(label) between 1 and 40),url text not null check(length(url)<=500 and url~'^https?://[^[:space:]]+$'),position integer not null default 0);
create index on public.midad_profile_links(user_id,position);
create table public.midad_showcase(project_id uuid primary key,user_id uuid not null,position integer not null default 0,featured boolean not null default false,foreign key(project_id,user_id) references public.midad_projects(id,user_id) on delete cascade);
create index on public.midad_showcase(user_id,position);
-- Preserve previously public works on already public profiles, without revealing other novels.
insert into public.midad_showcase(project_id,user_id,position) select distinct p.id,p.user_id,0 from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id join public.midad_books b on b.id=c.book_id join public.midad_projects p on p.id=b.project_id join public.midad_profiles pr on pr.user_id=p.user_id and pr.is_public;
create table public.midad_genres(code text primary key,name_ar text not null,name_en text not null);
insert into public.midad_genres values ('fantasy','فانتازيا','Fantasy'),('science-fiction','خيال علمي','Science fiction'),('romance','رومانسية','Romance'),('mystery','غموض','Mystery'),('thriller','إثارة وتشويق','Thriller'),('horror','رعب','Horror'),('adventure','مغامرة','Adventure'),('action','أكشن','Action'),('drama','دراما','Drama'),('comedy','كوميديا','Comedy'),('historical','تاريخية','Historical'),('litrpg','ألعاب وأنظمة — LitRPG','LitRPG'),('cultivation','فنون قتالية وارتقاء','Cultivation'),('slice-of-life','حياة يومية','Slice of life'),('psychological','نفسية','Psychological'),('dystopian','عوالم ديستوبية','Dystopian'),('sports','رياضة','Sports'),('literary','أدب واقعي','Literary fiction');
create table public.midad_novel_metadata(project_id uuid primary key,user_id uuid not null,status text not null default 'ongoing' check(status in('ongoing','completed','hiatus')),age_rating text not null default 'all' check(age_rating in('all','16+','18+')),language text not null default 'ar' check(language in('ar','en','other')),warnings text[] not null default '{}' check(warnings<@array['violence','strong-language','death','abuse','sexual-themes']),foreign key(project_id,user_id) references public.midad_projects(id,user_id) on delete cascade);
create table public.midad_project_genres(project_id uuid not null,user_id uuid not null,genre_code text not null references public.midad_genres(code),primary key(project_id,genre_code),foreign key(project_id,user_id) references public.midad_projects(id,user_id) on delete cascade);
create index on public.midad_project_genres(genre_code,project_id);
create table public.midad_novel_tags(project_id uuid not null,user_id uuid not null,tag text not null check(length(tag) between 1 and 40 and tag=lower(trim(tag))),primary key(project_id,tag),foreign key(project_id,user_id) references public.midad_projects(id,user_id) on delete cascade);
create index on public.midad_novel_tags(tag,project_id);
create table public.midad_follows(follower_id uuid not null references auth.users(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,author_id),check(follower_id<>author_id));
create index on public.midad_follows(author_id);
create table public.midad_ratings(project_id uuid not null references public.midad_projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,score integer not null check(score between 1 and 5),updated_at timestamptz not null default now(),primary key(project_id,user_id));
create index on public.midad_ratings(user_id);
create table public.midad_reading_list(project_id uuid not null references public.midad_projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(project_id,user_id));
create index on public.midad_reading_list(user_id,created_at desc);
create function midad_private.public_novel(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.midad_publications pub join public.midad_chapters c on c.id=pub.chapter_id join public.midad_books b on b.id=c.book_id where b.project_id=pid and c.draft_id is null) or exists(select 1 from public.midad_showcase s join public.midad_profiles p on p.user_id=s.user_id where s.project_id=pid and p.is_public)$$;
create function midad_private.public_asset(asset text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.midad_profiles p where p.is_public and asset like p.user_id::text||'/%' and asset in(p.avatar_path,p.banner_path)) or exists(select 1 from public.midad_projects p where p.cover_path=asset and asset like p.user_id::text||'/%' and midad_private.public_novel(p.id))$$;
grant usage on schema midad_private to anon;
revoke all on function midad_private.public_novel(uuid),midad_private.public_asset(text) from public;
grant execute on function midad_private.public_novel(uuid),midad_private.public_asset(text) to anon,authenticated;
create policy midad_public_images on storage.objects for select to anon,authenticated using(bucket_id='midad-assets' and midad_private.public_asset(name));
do $$declare tab text;begin foreach tab in array array['profile_links','showcase','novel_metadata','project_genres','novel_tags','genres','follows','ratings','reading_list'] loop execute format('alter table public.midad_%I enable row level security',tab);end loop;foreach tab in array array['profile_links','showcase','novel_metadata','project_genres','novel_tags'] loop execute format('create policy owner_select on public.midad_%I for select to authenticated using(user_id=(select auth.uid()))',tab);execute format('create policy owner_insert on public.midad_%I for insert to authenticated with check(user_id=(select auth.uid()))',tab);execute format('create policy owner_update on public.midad_%I for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()))',tab);execute format('create policy owner_delete on public.midad_%I for delete to authenticated using(user_id=(select auth.uid()))',tab);execute format('grant select,insert,update,delete on public.midad_%I to authenticated',tab);end loop;end$$;
create policy genre_read on public.midad_genres for select to anon,authenticated using(true);grant select on public.midad_genres to anon,authenticated;
create policy follow_read on public.midad_follows for select to authenticated using(follower_id=(select auth.uid()));
create policy follow_add on public.midad_follows for insert to authenticated with check(follower_id=(select auth.uid()) and follower_id<>author_id and exists(select 1 from public.midad_profiles p where p.user_id=author_id and p.is_public));
create policy follow_remove on public.midad_follows for delete to authenticated using(follower_id=(select auth.uid()));grant select,insert,delete on public.midad_follows to authenticated;
create policy rating_read on public.midad_ratings for select to authenticated using(user_id=(select auth.uid()));
create policy rating_add on public.midad_ratings for insert to authenticated with check(user_id=(select auth.uid()) and midad_private.public_novel(project_id) and not midad_private.can_write(project_id));
create policy rating_edit on public.midad_ratings for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and midad_private.public_novel(project_id) and not midad_private.can_write(project_id));
create policy rating_remove on public.midad_ratings for delete to authenticated using(user_id=(select auth.uid()));grant select,insert,update,delete on public.midad_ratings to authenticated;
create policy reading_read on public.midad_reading_list for select to authenticated using(user_id=(select auth.uid()));create policy reading_add on public.midad_reading_list for insert to authenticated with check(user_id=(select auth.uid()) and midad_private.public_novel(project_id));create policy reading_remove on public.midad_reading_list for delete to authenticated using(user_id=(select auth.uid()));grant select,insert,delete on public.midad_reading_list to authenticated;
create function public.midad_save_writer_profile(p_profile jsonb,p_links jsonb,p_showcase jsonb) returns void language plpgsql security invoker set search_path='' as $$declare uid uuid:=auth.uid(); l jsonb; r jsonb;begin
 if uid is null then raise exception 'login_required';end if;
 if jsonb_typeof(p_links)<>'array' or jsonb_array_length(p_links)>5 or jsonb_typeof(p_showcase)<>'array' or jsonb_array_length(p_showcase)>100 then raise exception 'invalid_input';end if;
 insert into public.midad_profiles(user_id,username,display_name,bio,is_public,tagline,location,avatar_path,banner_path) values(uid,lower(trim(p_profile->>'username')),trim(p_profile->>'display_name'),coalesce(p_profile->>'bio',''),coalesce((p_profile->>'is_public')::boolean,false),coalesce(p_profile->>'tagline',''),coalesce(p_profile->>'location',''),nullif(p_profile->>'avatar_path',''),nullif(p_profile->>'banner_path','')) on conflict(user_id) do update set username=excluded.username,display_name=excluded.display_name,bio=excluded.bio,is_public=excluded.is_public,tagline=excluded.tagline,location=excluded.location,avatar_path=excluded.avatar_path,banner_path=excluded.banner_path;
 delete from public.midad_profile_links where user_id=uid;for l in select value from jsonb_array_elements(p_links) loop insert into public.midad_profile_links(user_id,label,url,position) values(uid,trim(l->>'label'),trim(l->>'url'),coalesce((l->>'position')::integer,0));end loop;
 delete from public.midad_showcase where user_id=uid;for r in select value from jsonb_array_elements(p_showcase) loop insert into public.midad_showcase(project_id,user_id,position,featured) values((r->>'project_id')::uuid,uid,coalesce((r->>'position')::integer,0),coalesce((r->>'featured')::boolean,false));end loop;
end$$;
revoke all on function public.midad_save_writer_profile(jsonb,jsonb,jsonb) from public,anon;grant execute on function public.midad_save_writer_profile(jsonb,jsonb,jsonb) to authenticated;
create function public.midad_save_novel_metadata(p_id uuid,p_metadata jsonb,p_genres text[],p_tags text[]) returns void language plpgsql security invoker set search_path='' as $$declare uid uuid:=auth.uid();g text;t text;begin
 if not exists(select 1 from public.midad_projects p where p.id=p_id and p.user_id=uid) then raise exception 'not_owner';end if;if cardinality(p_genres)>4 or cardinality(p_tags)>12 then raise exception 'too_many_tags';end if;
 insert into public.midad_novel_metadata(project_id,user_id,status,age_rating,language,warnings) values(p_id,uid,coalesce(p_metadata->>'status','ongoing'),coalesce(p_metadata->>'age_rating','all'),coalesce(p_metadata->>'language','ar'),coalesce(array(select jsonb_array_elements_text(p_metadata->'warnings')),'{}')) on conflict(project_id) do update set status=excluded.status,age_rating=excluded.age_rating,language=excluded.language,warnings=excluded.warnings;
 delete from public.midad_project_genres where project_id=p_id;foreach g in array p_genres loop insert into public.midad_project_genres values(p_id,uid,g);end loop;
 delete from public.midad_novel_tags where project_id=p_id;foreach t in array p_tags loop insert into public.midad_novel_tags values(p_id,uid,lower(trim(t))) on conflict do nothing;end loop;
end$$;
revoke all on function public.midad_save_novel_metadata(uuid,jsonb,text[],text[]) from public,anon;grant execute on function public.midad_save_novel_metadata(uuid,jsonb,text[],text[]) to authenticated;
create function public.midad_catalog(p_query text default '',p_genre text default '',p_status text default '',p_age text default '',p_sort text default 'recent',p_author uuid default null,p_profile_only boolean default false,p_limit integer default 24,p_offset integer default 0) returns table(id uuid,title text,description text,cover_path text,author_id uuid,author_name text,author_username text,author_avatar text,genres text[],tags text[],status text,age_rating text,language text,warnings text[],chapter_count bigint,word_count bigint,rating_avg numeric,rating_count bigint,rank_score numeric,updated_at timestamptz,featured boolean) language sql stable security definer set search_path='' as $$
 with pub as(select b.project_id,count(distinct c.id) as chapters,coalesce(sum((select coalesce(sum(case when trim(s.plain_text)='' then 0 else cardinality(regexp_split_to_array(trim(s.plain_text),E'\\s+')) end),0) from public.midad_scenes s where s.chapter_id=c.id)),0) as words from public.midad_publications pp join public.midad_chapters c on c.id=pp.chapter_id and c.draft_id is null join public.midad_books b on b.id=c.book_id group by b.project_id),ratings as(select r.project_id,round(avg(r.score),2) as average,count(*) as n,(sum(r.score)+17.5)/(count(*)+5) as confidence from public.midad_ratings r group by r.project_id),data as(
 select p.id,p.title,p.description,p.cover_path,p.user_id as author_id,coalesce(pr.display_name,'كاتب في مِداد') as author_name,pr.username as author_username,case when pr.is_public then pr.avatar_path end as author_avatar,array(select g.genre_code from public.midad_project_genres g where g.project_id=p.id order by g.genre_code) as genres,array(select t.tag from public.midad_novel_tags t where t.project_id=p.id order by t.tag) as tags,coalesce(m.status,'ongoing') as status,coalesce(m.age_rating,'all') as age_rating,coalesce(m.language,'ar') as language,coalesce(m.warnings,'{}') as warnings,coalesce(pub.chapters,0) as chapter_count,coalesce(pub.words,0)::bigint as word_count,coalesce(r.average,0) as rating_avg,coalesce(r.n,0) as rating_count,coalesce(r.confidence,0) as rank_score,p.updated_at,coalesce(s.featured,false) as featured,coalesce(s.position,0) as shelf_position,s.project_id is not null and pr.is_public as in_profile
 from public.midad_projects p left join public.midad_profiles pr on pr.user_id=p.user_id left join public.midad_showcase s on s.project_id=p.id left join public.midad_novel_metadata m on m.project_id=p.id left join pub on pub.project_id=p.id left join ratings r on r.project_id=p.id where midad_private.public_novel(p.id))
 select d.id,d.title,d.description,d.cover_path,d.author_id,d.author_name,d.author_username,d.author_avatar,d.genres,d.tags,d.status,d.age_rating,d.language,d.warnings,d.chapter_count,d.word_count,d.rating_avg,d.rating_count,d.rank_score,d.updated_at,d.featured from data d where (p_author is null or d.author_id=p_author) and (not p_profile_only or d.in_profile) and (p_query='' or concat_ws(' ',d.title,d.description,d.author_name,d.author_username,array_to_string(d.tags,' ')) ilike '%'||left(p_query,150)||'%') and(p_genre='' or p_genre=any(d.genres)) and(p_status='' or d.status=p_status) and(p_age='' or d.age_rating=p_age)
 order by case when p_sort='rating' then (d.rating_count>0)::integer end desc nulls last,case when p_sort='rating' then d.rank_score end desc nulls last,case when p_sort='popular' then d.rating_count end desc nulls last,case when p_sort='profile' then d.featured::integer end desc nulls last,case when p_sort='profile' then d.shelf_position end asc nulls last,d.updated_at desc,d.id limit least(greatest(p_limit,1),100) offset least(greatest(p_offset,0),10000)
 $$;
revoke all on function public.midad_catalog(text,text,text,text,text,uuid,boolean,integer,integer) from public;grant execute on function public.midad_catalog(text,text,text,text,text,uuid,boolean,integer,integer) to anon,authenticated;
create function public.midad_writer_profile(handle text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare p public.midad_profiles;books jsonb;begin
 select * into p from public.midad_profiles where username=lower(handle) and is_public;if p.user_id is null then return null;end if;
 select coalesce(jsonb_agg(to_jsonb(n)),'[]') into books from public.midad_catalog(p_author=>p.user_id,p_profile_only=>true,p_sort=>'profile',p_limit=>100) n;
 return jsonb_build_object('user_id',p.user_id,'username',p.username,'display_name',p.display_name,'bio',p.bio,'tagline',p.tagline,'location',p.location,'avatar_path',p.avatar_path,'banner_path',p.banner_path,'created_at',p.created_at,'links',coalesce((select jsonb_agg(jsonb_build_object('label',l.label,'url',l.url) order by l.position,l.id) from public.midad_profile_links l where l.user_id=p.user_id),'[]'),'books',books,'followers',(select count(*) from public.midad_follows f where f.author_id=p.user_id),'following',(select count(*) from public.midad_follows f where f.follower_id=p.user_id));end$$;
revoke all on function public.midad_writer_profile(text) from public;grant execute on function public.midad_writer_profile(text) to anon,authenticated;
